// gh-2042 — release asset immutability gate (scripts/release_asset_gate.sh).
//
// The v1.0.680 incident: the daily build-macos train re-attached fresh
// fa-macos-arm64 assets to the ALREADY-PUBLISHED release ~2-3h AFTER the
// signed SHA256SUMS was attached — the manifest never re-ran, and every
// `fa update` provenance check on the train failed. Contract (AC1): a
// PUBLISHED release is immutable for `fa-*` assets — a post-publish attach
// must skip already-attached assets, refuse unattached fa-* assets loudly,
// and still allow the non-fa clobber-refresh (store AAB/IPA/APK artifacts
// are deliberately not provenance-covered, scripts/release_required_assets.txt).
// Drafts (and missing releases — the caller creates the draft first) attach
// exactly as before.
//
// Behavioral coverage follows release_hygiene_test.dart's style: a stubbed
// `gh` on PATH answering from fixture files, every invocation logged.
import 'dart:io';

import 'package:test/test.dart';

import 'release_hygiene_test_support.dart';

void main() {
  GateRun runGate(
    String name, {
    String? releaseState,
    List<String> attachedNames = const [],
    List<String> assets = const ['fa-linux-x64.tar.gz'],
    List<String> viewSeq = const [],
  }) {
    final dir = Directory(
      '${hygieneFixtureRoot.path}/gate-$name-${DateTime.now().microsecondsSinceEpoch}',
    )..createSync(recursive: true);
    final bin = stubGh(dir.path);
    if (releaseState != null) {
      File('${dir.path}/release-state.txt').writeAsStringSync('$releaseState\n');
    }
    if (attachedNames.isNotEmpty) {
      File(
        '${dir.path}/asset-names.txt',
      ).writeAsStringSync('${attachedNames.join('\n')}\n');
    }
    if (viewSeq.isNotEmpty) {
      File('${dir.path}/view-seq.txt').writeAsStringSync(
        '${viewSeq.join('\n')}\n',
      );
    }
    for (final asset in assets) {
      File('${dir.path}/$asset').writeAsStringSync('bytes of $asset');
    }
    File('${dir.path}/log').writeAsStringSync('');
    final res = Process.runSync('bash', [
      File('scripts/release_asset_gate.sh').absolute.path,
      'v1.2.3',
      ...assets,
    ], environment: {
      'PATH': '$bin:${Platform.environment['PATH']}',
      'GITHUB_REPOSITORY': 'OWNER/REPO',
      'GH_STUB_DIR': dir.path,
      'GH_LOG_FILE': '${dir.path}/log',
      'GH_TOKEN': 'stub',
    });
    return GateRun(
      res.exitCode,
      '${res.stdout}${res.stderr}',
      File('${dir.path}/log').readAsLinesSync(),
    );
  }

  test('missing gate script fails the suite loudly', () {
    expect(File('scripts/release_asset_gate.sh').existsSync(), isTrue,
        reason: 'scripts/release_asset_gate.sh must exist (gh-2042 AC1)');
  });

  test('draft release → attach: every asset uploaded --clobber, exit 0', () {
    // Default fixture state (no release-state.txt) = draft: the pre-gate
    // behavior every existing release test pins must be untouched.
    final run = runGate('draft', assets: ['fa-linux-x64.tar.gz', 'a.zip']);
    expect(run.exitCode, 0, reason: run.out);
    expect(
      run.log,
      contains('release upload v1.2.3 fa-linux-x64.tar.gz --clobber --repo OWNER/REPO'),
    );
    expect(
      run.log,
      contains('release upload v1.2.3 a.zip --clobber --repo OWNER/REPO'),
    );
    expect(run.log.where((l) => l.contains('release edit')), isEmpty,
        reason: 'the gate never publishes — provenance owns the flip');
  });

  test('published release + fa-* NOT attached → loud refusal, NOTHING uploaded', () {
    // The v1.0.680 shape: re-attaching an unattached fa-* asset to a
    // published release invalidates the signed manifest. Refuse before any
    // upload — a red leg, never silent drift.
    final run = runGate('published-fa', releaseState: 'false',
        attachedNames: ['fa-web-spa.zip'], assets: ['fa-macos-arm64.tar.gz']);
    expect(run.exitCode, isNot(0), reason: run.out);
    expect(run.out, contains('::error::'));
    expect(run.out, contains('fa-macos-arm64.tar.gz'));
    expect(run.out.toLowerCase(), contains('published'),
        reason: 'the refusal must name the immutability contract');
    expect(
      run.log.where((l) => l.contains('release upload')),
      isEmpty,
      reason: 'a refused attach uploads nothing',
    );
    expect(run.log.where((l) => l.contains('release edit')), isEmpty);
  });

  test('published release + fa-* ALREADY attached → immutable skip, exit 0, no upload', () {
    // The release-twin binaries re-run: same tag commit, asset already on
    // the published release. Skip — rebuilding + clobbering would drift the
    // manifest for the minutes until provenance re-signs (and the re-request
    // is a job rerun away anyway).
    final run = runGate('published-skip', releaseState: 'false',
        attachedNames: ['fa-linux-x64.tar.gz', 'SHA256SUMS', 'SHA256SUMS.sig'],
        assets: ['fa-linux-x64.tar.gz']);
    expect(run.exitCode, 0, reason: run.out);
    expect(run.log.where((l) => l.contains('release upload')), isEmpty,
        reason: 'an already-attached asset on a published release is skipped');
    expect(run.log.where((l) => l.contains('release edit')), isEmpty);
    expect(run.out.toLowerCase(), contains('skip'));
  });

  test('published release + non-fa asset → clobber-refresh stays allowed', () {
    // Store artifacts (AAB/IPA/APK) and DMG refreshers are deliberately not
    // provenance-covered (release_required_assets.txt scope note) — the
    // daily mobile leg keeps refreshing them.
    final run = runGate('published-nonfa', releaseState: 'false',
        attachedNames: ['fa-linux-x64.tar.gz'],
        assets: ['app-release.aab']);
    expect(run.exitCode, 0, reason: run.out);
    expect(
      run.log,
      contains('release upload v1.2.3 app-release.aab --clobber --repo OWNER/REPO'),
    );
  });

  test('published release + mixed list (one unattached fa-*) → refuse ALL, nothing uploaded', () {
    // Loop/collection contract: one bad asset must refuse the WHOLE list —
    // a partial attach would still drift the manifest.
    final run = runGate('published-mixed', releaseState: 'false',
        attachedNames: ['fa-linux-x64.tar.gz'],
        assets: ['fa-linux-x64.tar.gz', 'fa-macos-arm64.tar.gz', 'app-release.aab']);
    expect(run.exitCode, isNot(0), reason: run.out);
    expect(run.out, contains('fa-macos-arm64.tar.gz'));
    expect(run.log.where((l) => l.contains('release upload')), isEmpty,
        reason: 'a mixed refusal uploads nothing — no partial mutation');
  });

  test('missing release → allow (the caller lazy-drafts first; upload surfaces real errors)', () {
    final run = runGate('missing', viewSeq: ['missing'],
        assets: ['fa-linux-x64.tar.gz']);
    expect(run.exitCode, 0, reason: run.out);
    expect(
      run.log,
      contains('release upload v1.2.3 fa-linux-x64.tar.gz --clobber --repo OWNER/REPO'),
    );
  });

  test('API blip (view fails without a not-found verdict) → fail CLOSED, no upload', () {
    final run = runGate('blip', viewSeq: ['error'], assets: ['fa-linux-x64.tar.gz']);
    expect(run.exitCode, isNot(0), reason: run.out);
    expect(run.out, contains('::error::'));
    expect(run.log.where((l) => l.contains('release upload')), isEmpty,
        reason: 'an undeterminable release state must never upload');
  });

  test('garbage state verdict (unparseable isDraft) → fail CLOSED, no upload', () {
    final run = runGate('garbage', releaseState: 'garbage',
        assets: ['fa-linux-x64.tar.gz']);
    expect(run.exitCode, isNot(0), reason: run.out);
    expect(run.out, contains('::error::'));
    expect(run.log.where((l) => l.contains('release upload')), isEmpty);
  });

  test('zero assets → loud refusal (caller bug, mirror of the gh-1801 refusal)', () {
    final dir = Directory(
      '${hygieneFixtureRoot.path}/gate-empty-${DateTime.now().microsecondsSinceEpoch}',
    )..createSync(recursive: true);
    final bin = stubGh(dir.path);
    File('${dir.path}/log').writeAsStringSync('');
    final res = Process.runSync('bash', [
      File('scripts/release_asset_gate.sh').absolute.path,
      'v1.2.3',
    ], environment: {
      'PATH': '$bin:${Platform.environment['PATH']}',
      'GITHUB_REPOSITORY': 'OWNER/REPO',
      'GH_STUB_DIR': dir.path,
      'GH_LOG_FILE': '${dir.path}/log',
      'GH_TOKEN': 'stub',
    });
    expect(res.exitCode, isNot(0));
    expect('${res.stdout}${res.stderr}', contains('::error::'));
  });
}

class GateRun {
  GateRun(this.exitCode, this.out, this.log);
  final int exitCode;
  final String out;
  final List<String> log;
}

// gh-2042 — release_attach_or_create.sh against a PUBLISHED release.
//
// The attach-or-create script's existing-release path (`upload_all`) is the
// v1.0.680 hole: it uploaded with --clobber into whatever release the tag
// resolved to — draft or published. Under AC1 the attach routes every asset
// through scripts/release_asset_gate.sh (published → skip attached fa-* /
// refuse unattached fa-* / allow non-fa), and the recovery publish+latest
// flip NEVER fires on a published release — `gh release edit --latest` on an
// older published release would drag the `latest` badge (and `fa update`)
// backwards to a downgrade.
//
// Reuses the release_hygiene_test.dart fixture harness (stubbed gh).
import 'dart:io';

import 'package:test/test.dart';

import 'release_hygiene_test_support.dart';

void main() {
  AttachOut runAttach(
    String name, {
    String? releaseState,
    List<String> attachedNames = const [],
    List<String> viewSeq = const ['exists'],
  }) {
    final dir = Directory(
      '${hygieneFixtureRoot.path}/immutable-$name-${DateTime.now().microsecondsSinceEpoch}',
    )..createSync(recursive: true);
    final bin = stubGh(dir.path);
    if (releaseState != null) {
      File('${dir.path}/release-state.txt').writeAsStringSync('$releaseState\n');
    }
    if (attachedNames.isNotEmpty) {
      File(
        '${dir.path}/asset-names.txt',
      ).writeAsStringSync('${attachedNames.join('\n')}\n');
    }
    File('${dir.path}/view-seq.txt').writeAsStringSync('${viewSeq.join('\n')}\n');
    File('${dir.path}/a.zip').writeAsStringSync('asset-a');
    File('${dir.path}/b.zip').writeAsStringSync('asset-b');
    File('${dir.path}/release-notes.md').writeAsStringSync('curated notes\n');
    File('${dir.path}/log').writeAsStringSync('');
    final res = Process.runSync('bash', [
      File('scripts/release_attach_or_create.sh').absolute.path,
      'v1.2.3',
      'a.zip',
      'b.zip',
    ], workingDirectory: dir.path, environment: {
      'PATH': '$bin:${Platform.environment['PATH']}',
      'GITHUB_REPOSITORY': 'OWNER/REPO',
      'GH_STUB_DIR': dir.path,
      'GH_LOG_FILE': '${dir.path}/log',
      'GITHUB_RUN_ID': '111',
      'GITHUB_JOB': 'release-macos',
    });
    return AttachOut(
      res.exitCode,
      '${res.stdout}${res.stderr}',
      File('${dir.path}/log').readAsLinesSync(),
      File('${dir.path}/last-create-notes.md').existsSync()
          ? File('${dir.path}/last-create-notes.md').readAsStringSync()
          : null,
    );
  }

  test('published release + unattached fa-* assets → attach refuses loud, nothing uploaded', () {
    // a.zip/b.zip stand in for the fa-* DMG/zip stable names the daily
    // release-macos leg attaches (the v1.0.680 shape).
    final run = runAttach('published-fa', releaseState: 'false',
        attachedNames: ['fa-web-spa.zip']);
    expect(run.exitCode, isNot(0), reason: run.out);
    expect(run.out, contains('::error::'));
    expect(
      run.log.where((l) => l.contains('release upload')),
      isEmpty,
      reason: 'a refused attach uploads nothing',
    );
    expect(run.log.where((l) => l.contains('release create')), isEmpty,
        reason: 'the release exists — a refusal must not create a twin');
    expect(run.log.where((l) => l.contains('release edit')), isEmpty);
  });

  test('published release + already-attached assets → immutable skip, exit 0, no upload', () {
    final run = runAttach('published-skip', releaseState: 'false',
        attachedNames: ['a.zip', 'b.zip']);
    expect(run.exitCode, 0, reason: run.out);
    expect(run.log.where((l) => l.contains('release upload')), isEmpty);
    expect(run.out.toLowerCase(), contains('skip'));
  });

  test('published release + non-fa assets only → clobber-refresh attaches, exit 0', () {
    // The mobile leg (AAB/IPA/APK — not provenance-covered) keeps its
    // store-refresh contract on published releases.
    final run = runAttach('published-nonfa', releaseState: 'false',
        attachedNames: ['fa-linux-x64.tar.gz']);
    expect(run.exitCode, 0, reason: run.out);
    expect(
      run.log.where((l) => l.contains('release upload v1.2.3 a.zip')),
      isNotEmpty,
      reason: 'non-fa assets keep the clobber-refresh path',
    );
  });

  test('published release + servable (SHA256SUMS attached) → NO publish flip (latest never drags backwards)', () {
    // Regression guard for the recovery path: on a DRAFT servable release
    // the attach publishes + flags latest (existing behavior, pinned by
    // release_hygiene_test.dart); on a PUBLISHED one the flip must stay
    // off — `--latest` here would move the badge to an older release.
    final run = runAttach('published-servable', releaseState: 'false',
        attachedNames: ['fa-linux-x64.tar.gz', 'SHA256SUMS', 'SHA256SUMS.sig']);
    expect(run.exitCode, 0, reason: run.out);
    expect(
      run.log.where((l) => l.contains('release edit')),
      isEmpty,
      reason:
          'a published release is never re-flaged latest by the attach '
          '(gh-2042: latest must never move backwards)',
    );
  });

  test('draft release + fa-* assets → attach unchanged (uploads --clobber)', () {
    // Default fixture state (no release-state.txt) = draft.
    final run = runAttach('draft-fa', attachedNames: []);
    expect(run.exitCode, 0, reason: run.out);
    expect(
      run.log,
      contains('release upload v1.2.3 a.zip --clobber --repo OWNER/REPO'),
    );
    expect(run.log.where((l) => l.contains('release edit')), isEmpty,
        reason: 'un-servable draft stays unflipped (gh-1801, unchanged)');
  });

  test('draft release + servable → recovery publish + latest (unchanged)', () {
    final run = runAttach('draft-servable',
        attachedNames: ['SHA256SUMS', 'SHA256SUMS.sig']);
    expect(run.exitCode, 0, reason: run.out);
    expect(
      run.log,
      contains('release edit v1.2.3 --draft=false --latest --repo OWNER/REPO'),
      reason: 'the draft recovery path stays (gh-1801 rework)',
    );
  });

  test('release_lazy_draft.sh on a published release → still a no-op skip (the gate owns refusal)', () {
    // lazy_draft only CREATES; its callers' uploads are gated. Its
    // existing-release skip must stay a green no-op for all states.
    final dir = Directory(
      '${hygieneFixtureRoot.path}/immutable-lazy-${DateTime.now().microsecondsSinceEpoch}',
    )..createSync(recursive: true);
    final bin = stubGh(dir.path);
    File('${dir.path}/release-state.txt').writeAsStringSync('false\n');
    File('${dir.path}/log').writeAsStringSync('');
    final res = Process.runSync('bash', [
      File('scripts/release_lazy_draft.sh').absolute.path,
      'v1.2.3',
    ], workingDirectory: dir.path, environment: {
      'PATH': '$bin:${Platform.environment['PATH']}',
      'GITHUB_REPOSITORY': 'OWNER/REPO',
      'GH_STUB_DIR': dir.path,
      'GH_LOG_FILE': '${dir.path}/log',
      'GITHUB_RUN_ID': '111',
      'GITHUB_JOB': 'binaries-linux-x64',
    });
    expect(res.exitCode, 0, reason: '${res.stdout}${res.stderr}');
    final log = File('${dir.path}/log').readAsLinesSync();
    expect(log.where((l) => l.contains('release create')), isEmpty);
  });
}

// gh-2042 AC2 — release_drift_check.sh: re-download every `fa-*` asset of a
// release and diff sha256 against the signed SHA256SUMS.
//
// The v1.0.680 incident shipped a manifest that no longer matched the
// attached bytes (post-publish re-attach), so `fa update` / install.sh
// provenance verification failed for every macOS-arm64 user. This check is
// the CI-side twin of bin/self_manage.dart's verifyReleaseProvenance: same
// manifest, same digest comparison — but it runs against the RELEASE, pages
// on drift, and never lingers.
//
// Behavioral tests run the script over fixture directories (FA_DRIFT_LOCAL_DIR,
// the documented test seam) with the REAL sha256sum — no gh needed.
import 'dart:io';

import 'package:test/test.dart';

String _out(ProcessResult r) => '${r.stdout}${r.stderr}';

/// Fixture dir with [assetContents] (name → bytes) plus SHA256SUMS built from
/// the REAL sha256sum over the [manifestNames] subset, and a dummy .sig.
Directory _fixture(
  String name,
  Map<String, String> assetContents,
  List<String> manifestNames,
) {
  final dir = Directory.systemTemp.createTempSync('drift-check-$name-');
  assetContents.forEach((assetName, content) {
    File('${dir.path}/$assetName').writeAsStringSync(content);
  });
  final args = ['sha256sum', ...manifestNames];
  final res = Process.runSync('sha256sum', manifestNames,
      workingDirectory: dir.path);
  if (res.exitCode != 0) fail('fixture sha256sum failed: ${res.stderr}');
  File('${dir.path}/SHA256SUMS').writeAsStringSync(res.stdout as String);
  File('${dir.path}/SHA256SUMS.sig').writeAsStringSync('dummy-signature');
  return dir;
}

ProcessResult _runCheck(Directory dir) => Process.runSync('bash', [
      'scripts/release_drift_check.sh',
      'v1.2.3',
    ], environment: {
      'GITHUB_REPOSITORY': 'OWNER/REPO',
      'GH_TOKEN': 'stub',
      'FA_DRIFT_LOCAL_DIR': dir.path,
    });

void main() {
  test('missing drift-check script fails the suite loudly', () {
    expect(File('scripts/release_drift_check.sh').existsSync(), isTrue,
        reason: 'scripts/release_drift_check.sh must exist (gh-2042 AC2)');
  });

  test('every fa-* digest matches the signed manifest → exit 0', () {
    // Multi-item set (loop contract): three assets, all matching.
    final dir = _fixture('match', {
      'fa-linux-x64.tar.gz': 'linux-bytes',
      'fa-macos-arm64.tar.gz': 'mac-bytes',
      'fa-web-spa.zip': 'spa-bytes',
    }, [
      'fa-linux-x64.tar.gz',
      'fa-macos-arm64.tar.gz',
      'fa-web-spa.zip',
    ]);
    final r = _runCheck(dir);
    expect(r.exitCode, 0, reason: _out(r));
    expect(_out(r), contains('✅'));
    dir.deleteSync(recursive: true);
  });

  test('tampered asset (manifest digest no longer matches bytes) → exit 1, names the asset', () {
    final dir = _fixture('tampered', {
      'fa-linux-x64.tar.gz': 'linux-bytes',
      'fa-macos-arm64.tar.gz': 'mac-bytes',
      'fa-web-spa.zip': 'spa-bytes',
    }, [
      'fa-linux-x64.tar.gz',
      'fa-macos-arm64.tar.gz',
      'fa-web-spa.zip',
    ]);
    // The post-publish re-attach: fresh bytes under an already-signed name.
    File('${dir.path}/fa-macos-arm64.tar.gz').writeAsStringSync('REPLACED');
    final r = _runCheck(dir);
    expect(r.exitCode, isNot(0), reason: _out(r));
    expect(_out(r), contains('::error::'));
    expect(_out(r), contains('fa-macos-arm64.tar.gz'));
    dir.deleteSync(recursive: true);
  });

  test('asset on disk but NOT in the manifest (stale manifest) → exit 1', () {
    final dir = _fixture('unlisted', {
      'fa-linux-x64.tar.gz': 'linux-bytes',
      'fa-macos-arm64-mac.zip': 'attached-after-signing',
    }, [
      'fa-linux-x64.tar.gz',
    ]);
    final r = _runCheck(dir);
    expect(r.exitCode, isNot(0), reason: _out(r));
    expect(_out(r), contains('fa-macos-arm64-mac.zip'),
        reason: 'the drift report must name the uncovered asset');
    dir.deleteSync(recursive: true);
  });

  test('SHA256SUMS missing on the release → exit 1 (provenance can never be verified)', () {
    final dir = _fixture('no-manifest', {'fa-linux-x64.tar.gz': 'b'}, [
      'fa-linux-x64.tar.gz',
    ]);
    File('${dir.path}/SHA256SUMS').deleteSync();
    final r = _runCheck(dir);
    expect(r.exitCode, isNot(0), reason: _out(r));
    expect(_out(r), contains('::error::'));
    expect(_out(r), contains('SHA256SUMS'));
    dir.deleteSync(recursive: true);
  });

  test('SHA256SUMS.sig missing → exit 1 (unsigned manifest is not provenance)', () {
    final dir = _fixture('no-sig', {'fa-linux-x64.tar.gz': 'b'}, [
      'fa-linux-x64.tar.gz',
    ]);
    File('${dir.path}/SHA256SUMS.sig').deleteSync();
    final r = _runCheck(dir);
    expect(r.exitCode, isNot(0), reason: _out(r));
